<style>
@page{size:A4 portrait;margin:10mm}
*{box-sizing:border-box}html,body{margin:0;padding:0}body{color:#17233a;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;line-height:1.35;-webkit-print-color-adjust:exact;print-color-adjust:exact}.sheet{width:100%;margin:0 auto}.letterhead{display:block;width:100%;height:auto;max-height:145px;margin:0 auto 4mm;object-fit:contain;object-position:center}.school-head{width:100%;min-height:24mm;margin:0 auto 4mm;padding:0 0 3mm;border-bottom:2px solid #0b3b83}.school-head img{float:left;width:17mm;height:17mm;margin-right:4mm;object-fit:contain}.school-head h1{margin:0;color:#0b3b83;font-size:13pt;font-weight:800;text-transform:uppercase}.school-head p{margin:1mm 0 0;color:#61738e;font-size:7.5pt}.clear{clear:both}.report-content{width:calc(100% - 12mm);margin:0 auto}.title{margin:3mm 0 3.5mm;text-align:center}.title h2{margin:0;color:#102d61;font-size:13pt;letter-spacing:.15px;text-transform:uppercase}.title p{margin:1mm 0 0;color:#52647d;font-size:7.5pt;font-weight:700}.period{display:inline-block;margin-top:1.5mm;border:1px solid #cbdced;border-radius:3mm;padding:1.4mm 3.5mm;background:#f5f9ff;color:#123e7b;font-size:7.5pt;font-weight:700}.summary{width:100%;border-collapse:separate;border-spacing:1.5mm;margin:0 0 3mm}.summary td{width:50%;padding:3.5mm 4mm;border:1px solid #dce5f0;background:#f8fafc;vertical-align:top}.summary small{display:block;color:#6d7e95;font-size:6.2pt;font-weight:700;letter-spacing:.3px;text-transform:uppercase}.summary strong{display:block;margin-top:1mm;color:#172238;font-size:10pt}h3{margin:3mm 0 1.4mm;color:#102d61;font-size:9.5pt}table{width:100%;border-collapse:collapse;table-layout:fixed;page-break-inside:auto}thead{display:table-header-group}tr{page-break-inside:avoid;page-break-after:auto}th{padding:1.7mm 1.5mm;background:#0b3b83;color:#fff;font-size:6.1pt;letter-spacing:.2px;text-align:left;text-transform:uppercase}td{padding:1.8mm 1.5mm;border:1px solid #dce5f0;vertical-align:top;font-size:7pt;overflow-wrap:anywhere}.date{width:16%}.student{width:27%}.bill{width:42%}.amount{width:15%}.right{text-align:right}.muted{display:block;margin-top:.6mm;color:#687b96;font-size:6.3pt}.total-row td{background:#edf4ff;color:#0b3b83;font-weight:800}.summary-type .type{width:70%}.summary-type .count{width:15%}.summary-type .total{width:15%}.signature{width:50mm;margin:6mm 0 0 auto;text-align:center;color:#53657e;font-size:7.5pt}.signature p{margin:0 0 1mm}.signature .line{margin:14mm 0 1.5mm;border-top:1px solid #7e8fa7}.footer{margin-top:4mm;padding-top:2mm;border-top:1px solid #dce5f0;color:#7c8aa0;font-size:6pt;text-align:center}.print-action{margin:8mm auto;text-align:center}.print-action button{border:0;border-radius:2mm;padding:3mm 5mm;background:#0b3b83;color:#fff;font-size:10pt;font-weight:700;cursor:pointer}@media screen{body{margin:12mm auto;max-width:210mm;background:#fff;box-shadow:0 0 0 1px #e2e8f0}}@media print{html,body{margin:0!important;padding:0!important;background:#fff!important}.sheet{width:100%!important;min-height:0!important}.print-action{display:none!important}.report-content{width:calc(100% - 12mm)!important}.letterhead,.school-head{width:100%!important}.summary{border-spacing:1.5mm}.signature{page-break-inside:avoid}}
</style>
</head>
